//! 🧪️ Real Original Source loans fund every output prefix, foreign-borrow refusal, typed capture and physical cleanup.
use super::*;
use semio_framework_job::{Generation,OperationId,OriginalTurnFailure,StepContext};
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
use semio_framework_job_native_decode::{OriginalNativeDecodeSource,OriginalNativeDecodePolicy,OriginalNativeDecodeIssued};
use semio_framework_value::{retirement::controlled::ControlledRetirement};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
#[derive(Debug,PartialEq,serde::Serialize,serde::Deserialize,semio_framework_value::NativeReceive,semio_framework_value::RetireOwned)]
#[serde(rename_all="camelCase",deny_unknown_fields)]
#[value(crate="::semio_framework_value",rename_all="camelCase",deny_unknown_fields)]
struct Projection{message:String,values:Vec<u8>}
fn clock()->Option<u64>{Some(1)}
fn funded<T>(caller:&mut OriginalJobFixtureCaller,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=observe(||caller.turn(g,run));let p=caller.receipt();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn issued(turn:RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>,g:RetainedCloneGrant)->OriginalNativeDecodeIssued<RetainedCloneStep,OriginalReceivingPrimary>{let progress=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.progress);OriginalNativeDecodeIssued{value:turn.result,grant:g,progress,work:turn.work}}
#[test]
fn unique_json_output_keeps_original_source_and_every_cancelled_typed_prefix(){
 let c:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let stock=&c["stock"];let g=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let limits=JsonReadLimits{maximum_bytes:2048,maximum_allocation_bytes:g.maximum_capacity_bytes,maximum_depth:16,maximum_items:10000};
 for row in c["cases"].as_array().unwrap(){for cut in std::iter::once(None).chain(c["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let wire=row["wire"].as_str().unwrap();let accepted=row["accepted"].as_bool().unwrap();let oracle=serde_json::from_str::<Projection>(wire);assert_eq!(oracle.is_ok(),accepted);let mut caller=OriginalJobFixtureCaller::admit(OperationId(941),Generation(1),g,clock,100000000,stock["fuel"].as_u64().unwrap());let mut decode=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:g.maximum_capacity_bytes});let mut frame:Option<OriginalJsonOutputReceiving<Projection>>=None;let mut captured=None;let mut failed=false;let mut checked_foreign=false;
  for at in 0..100000{if cut==Some(at){break}let outcome=funded(&mut caller,g,|cx|decode.receive_step(cx,|control,grant|{if let Some(frame)=frame.as_mut(){issued(frame.advance(wire.as_bytes(),control,4096,grant),grant)}else{let d=OriginalJsonOutputReceiving::<Projection>::constructor_demand();if !retained_clone_grant_admits(grant,d){return issued(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0},grant)}match OriginalJsonOutputReceiving::admit(wire.as_bytes(),limits,control,grant){Ok((value,p))=>{frame=Some(value);issued(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(p)),work:1},grant)},Err(error)=>issued(RetainedWorkOutcome{result:Err(error.into()),work:0},grant)}}}));let Some(outcome)=outcome else{continue};assert!(outcome.receiving_refusal.is_none());if outcome.value.is_err(){failed=true;break}
   if !checked_foreign{let foreign=wire.as_bytes().to_vec();let result=funded(&mut caller,g,|cx|decode.receive_step(cx,|control,grant|issued(frame.as_mut().unwrap().advance(&foreign,control,4096,grant),grant))).unwrap();assert!(result.receiving_refusal.is_none());assert!(result.value.is_err());assert_eq!(result.progress,Default::default());assert_eq!(result.work,0);checked_foreign=true;}
   if frame.as_ref().is_some_and(|owner|owner.ready()){let result=funded(&mut caller,g,|cx|decode.receive_step(cx,|_,grant|{let turn=frame.as_mut().unwrap().take_into(&mut captured,grant);let progress=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(ValueError::retained_progress);OriginalNativeDecodeIssued{value:turn.result,progress,grant,work:turn.work}})).unwrap();assert!(result.receiving_refusal.is_none());result.value.unwrap();break}assert!(at<99999);
  }
  if cut.is_none(){assert_eq!(failed,!accepted);assert_eq!(captured.is_some(),accepted);if let Some(value)=captured.as_ref(){assert_eq!(value,&oracle.unwrap());}}
  caller.cancel().cancel_now();if let Some(owner)=frame.as_mut(){owner.begin_close();for at in 0..100000{if owner.terminal_is_empty(){break}let result=funded(&mut caller,g,|cx|decode.close_producer_step(cx,|control,grant|{let mut work=0;let value=control.with_retirement(grant,|retirement|{let turn=owner.close_step(retirement,grant);work=turn.work;turn.result});let progress=value.as_ref().map(|s|s.progress()).unwrap_or_else(ValueError::retained_progress);OriginalNativeDecodeIssued{value,grant,progress,work}})).unwrap();assert!(result.receiving_refusal.is_none());result.value.unwrap();assert!(at<99999)}assert!(owner.terminal_is_empty());}drop(frame);
  if let Some(value)=captured{let(mut close,heap)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|panic!("unique captured output supports controlled retirement")));assert_eq!(heap,(0,0));for at in 0..100000{if close.terminal_is_empty(){break}let result=funded(&mut caller,g,|cx|decode.close_producer_step(cx,|control,grant|{let mut work=0;let value=control.with_retirement(grant,|retirement|{let d=close.next_demand(grant.maximum_copy_bytes)?;if d.capacity_bytes!=0{retirement.charge(d.capacity_bytes)?}let value=close.step(grant);work=close.last_turn_work();value});let progress=value.as_ref().map(|s|s.progress()).unwrap_or_else(ValueError::retained_progress);OriginalNativeDecodeIssued{value,grant,progress,work}})).unwrap();assert!(result.receiving_refusal.is_none());result.value.unwrap();assert!(at<99999)}assert!(close.terminal_is_empty());}
  for at in 0..100000{if decode.terminal_is_empty(){break}funded(&mut caller,g,|cx|decode.close_step(cx));assert!(at<99999)}assert!(decode.terminal_is_empty());assert!(caller.fuel_remaining()>0);caller.retire(g);
 }}
}

#[test]
fn source_owned_unique_output_returns_real_typed_capture_before_decoder_retirement(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1000000,maximum_copy_bytes:16777216,maximum_capacity_bytes:16777216,maximum_release_bytes:16777216,maximum_depth:64};
 for row in corpus["cases"].as_array().unwrap(){for cut in std::iter::once(None).chain(corpus["cancelPrefixes"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize))){let wire=row["wire"].as_str().unwrap();let oracle=serde_json::from_str::<Projection>(wire);let mut caller=OriginalJobFixtureCaller::admit(OperationId(942),Generation(1),g,clock,100000000,1000000);let mut state=OriginalJsonOutputSource::<Projection>::new(OriginalNativeDecodePolicy{maximum_owned_bytes:g.maximum_capacity_bytes},JsonReadLimits{maximum_bytes:2048,maximum_allocation_bytes:g.maximum_capacity_bytes,maximum_depth:16,maximum_items:10000});let mut captured=None;let mut refused=false;
  for at in 0..100000{if cut==Some(at){break}let outcome=funded(&mut caller,g,|cx|if state.ready(){state.take_step(&mut captured,cx)}else{state.receive_step(wire.as_bytes(),cx)});if let Some(outcome)=outcome{assert!(outcome.receiving_refusal.is_none());let failed=outcome.value.is_err();let mut close=ControlledRetirement::retain(outcome);for step in 0..100000{if close.terminal_is_empty(){break}if let Some(receipt)=funded(&mut caller,g,|cx|state.close_owned_step(&mut close,cx)){assert!(receipt.receiving_refusal.is_none());receipt.value.unwrap();}assert!(step<99999)}if failed{refused=true;break}}if captured.is_some(){break}assert!(at<99999)}if cut.is_none(){assert_eq!(refused,oracle.is_err());assert_eq!(captured.as_ref(),oracle.as_ref().ok());}
  caller.cancel().cancel_now();if let Some(value)=captured{let mut close=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("captured output supports controlled retirement"));for at in 0..100000{if close.terminal_is_empty(){break}if let Some(outcome)=funded(&mut caller,g,|cx|state.close_owned_step(&mut close,cx)){assert!(outcome.receiving_refusal.is_none());outcome.value.unwrap();}assert!(at<99999)}}for at in 0..100000{if state.terminal_is_empty(){break}match funded(&mut caller,g,|cx|state.close_step(cx)){OriginalJsonOutputClose::Producer(Some(outcome))=>{assert!(outcome.receiving_refusal.is_none());outcome.value.unwrap();},_=>{}}assert!(at<99999)}assert!(state.terminal_is_empty());assert!(caller.fuel_remaining()>0);caller.retire(g);
 }}
}
